import React, { useState } from 'react';

export default function StudentActivities({ activities, selectedSubject, studentSubjects, onSelectSubject }) {
  const [selectedLesson, setSelectedLesson] = useState('All');
  const [selectedType, setSelectedType] = useState('All');
  const [answers, setAnswers] = useState({});

  const cleanTxt = (str) => (str || '').replace(/\$|\{|\}/g, '');
  const parseNum = (str) => parseInt((str || '').replace(/\D/g, '')) || 0;

  const getActivityType = (act) => {
    const type = (act.question_type || '').toLowerCase();
    if (type.includes('true') || type.includes('tf')) return 'True/False';
    if (type.includes('mcq')) return 'MCQ';
    if (type.includes('short')) return 'Short Answer';

    const optA = (act.option_a || '').toUpperCase().trim();
    if (optA === 'TRUE' || !act.option_c) return 'True/False';
    if (act.option_c || act.option_d) return 'MCQ';
    return 'Short Answer';
  };

  // Filter Activities by Subject, Lesson & Type
  const subjectActivities = activities.filter(a => 
    (a.subject || a.subject_name || '').toLowerCase().includes(selectedSubject.toLowerCase())
  );

  const availableLessons = Array.from(
    new Set(subjectActivities.map(a => a.lesson_name?.trim()).filter(Boolean))
  ).sort((a, b) => parseNum(b) - parseNum(a));

  const filteredList = subjectActivities.filter(a => {
    if (selectedLesson !== 'All' && (a.lesson_name || '').toLowerCase() !== selectedLesson.toLowerCase()) return false;
    if (selectedType !== 'All' && getActivityType(a) !== selectedType) return false;
    return true;
  });

  return (
    <div style={styles.whiteBox}>
      {/* Header with Subject Tabs */}
      <div style={styles.tabHeader}>
        <div>
          <h2 style={{ margin: 0, fontSize: '18px', color: '#145c2e', fontWeight: 'bold' }}>
            🧩 Lesson Activities - <span style={{ color: '#16a34a' }}>{selectedSubject}</span>
          </h2>
          <p style={{ margin: '3px 0 0 0', fontSize: '12px', color: '#64748b' }}>Interactive practice tasks for {selectedSubject}</p>
        </div>

        <div style={{ display: 'flex', gap: '6px' }}>
          {studentSubjects.map(sub => (
            <button
              key={sub}
              onClick={() => { onSelectSubject(sub); setSelectedLesson('All'); }}
              style={{
                border: 'none', padding: '6px 14px', borderRadius: '16px', fontSize: '12px', fontWeight: 'bold', cursor: 'pointer',
                backgroundColor: selectedSubject === sub ? '#145c2e' : '#f1f5f9',
                color: selectedSubject === sub ? '#fff' : '#475569'
              }}
            >
              {sub}
            </button>
          ))}
        </div>
      </div>

      {/* Filter Bar */}
      <div style={styles.filterBar}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
          <span style={{ fontSize: '12px', fontWeight: 'bold', color: '#145c2e' }}>📘 Select Lesson:</span>
          <select value={selectedLesson} onChange={(e) => setSelectedLesson(e.target.value)} style={styles.selectInput}>
            <option value="All">All Lessons</option>
            {availableLessons.map(les => <option key={les} value={les}>{les}</option>)}
          </select>
        </div>

        <div style={{ display: 'flex', gap: '6px' }}>
          {['All', 'True/False', 'MCQ', 'Short Answer'].map(t => (
            <button
              key={t}
              onClick={() => setSelectedType(t)}
              style={{
                padding: '6px 12px', borderRadius: '14px', fontSize: '11.5px', fontWeight: 'bold', cursor: 'pointer',
                border: '1px solid #cbd5e1',
                backgroundColor: selectedType === t ? '#145c2e' : '#ffffff',
                color: selectedType === t ? '#ffffff' : '#475569'
              }}
            >
              {t === 'All' ? '📋 All Types' : t}
            </button>
          ))}
        </div>
      </div>

      {/* Questions List (No Score Card at Bottom) */}
      <div style={{ display: 'flex', flexDirection: 'column', gap: '14px' }}>
        {filteredList.map((act, index) => {
          const type = getActivityType(act);

          return (
            <div key={act.id} style={styles.activityCard}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '10px' }}>
                <span style={{ fontSize: '13.5px', fontWeight: 'bold', color: '#145c2e' }}>
                  Question {String(index + 1).padStart(2, '0')}
                </span>
                <span style={{ fontSize: '11px', backgroundColor: '#ecfdf5', color: '#15803d', border: '1px solid #bbf7d0', padding: '2px 8px', borderRadius: '10px', fontWeight: 'bold' }}>
                  {type}
                </span>
              </div>

              <p style={{ fontSize: '13.5px', margin: '0 0 14px 0', color: '#1e293b', fontWeight: '500', lineHeight: '1.5' }}>
                {cleanTxt(act.question_text)}
              </p>

              {/* 1. True/False */}
              {type === 'True/False' && (
                <div style={{ display: 'flex', gap: '10px', maxWidth: '380px' }}>
                  {['TRUE', 'FALSE'].map(opt => (
                    <button
                      key={opt}
                      onClick={() => setAnswers({ ...answers, [act.id]: opt })}
                      style={{
                        flex: 1, padding: '9px', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '12.5px',
                        border: answers[act.id] === opt ? '2px solid #145c2e' : '1px solid #cbd5e1',
                        backgroundColor: answers[act.id] === opt ? '#d1fae5' : '#ffffff',
                        color: answers[act.id] === opt ? '#145c2e' : '#475569'
                      }}
                    >
                      {opt === 'TRUE' ? '✅ TRUE' : '❌ FALSE'}
                    </button>
                  ))}
                </div>
              )}

              {/* 2. MCQ */}
              {type === 'MCQ' && (
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '10px', maxWidth: '680px' }}>
                  {[
                    { k: 'A', txt: act.option_a }, { k: 'B', txt: act.option_b },
                    { k: 'C', txt: act.option_c }, { k: 'D', txt: act.option_d }
                  ].filter(o => Boolean(o.txt)).map(o => (
                    <div
                      key={o.k}
                      onClick={() => setAnswers({ ...answers, [act.id]: o.k })}
                      style={{
                        padding: '10px 14px', borderRadius: '8px', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '8px', fontSize: '13px',
                        border: answers[act.id] === o.k ? '2px solid #145c2e' : '1px solid #e2e8f0',
                        backgroundColor: answers[act.id] === o.k ? '#f0fdf4' : '#ffffff',
                        color: answers[act.id] === o.k ? '#145c2e' : '#334155',
                        fontWeight: answers[act.id] === o.k ? 'bold' : 'normal'
                      }}
                    >
                      <span style={{ backgroundColor: answers[act.id] === o.k ? '#145c2e' : '#f1f5f9', color: answers[act.id] === o.k ? '#fff' : '#64748b', borderRadius: '50%', width: '22px', height: '22px', display: 'inline-flex', alignItems: 'center', justifyContent: 'center', fontSize: '11px', fontWeight: 'bold' }}>
                        {o.k}
                      </span>
                      {cleanTxt(o.txt)}
                    </div>
                  ))}
                </div>
              )}

              {/* 3. Short Answer */}
              {type === 'Short Answer' && (
                <input
                  type="text"
                  placeholder="Type your answer here..."
                  value={answers[act.id] || ''}
                  onChange={(e) => setAnswers({ ...answers, [act.id]: e.target.value })}
                  style={styles.textInput}
                />
              )}
            </div>
          );
        })}

        {filteredList.length === 0 && (
          <p style={{ color: '#94a3b8', fontStyle: 'italic', padding: '25px', textAlign: 'center', fontSize: '13px' }}>
            No activities published for this selection yet.
          </p>
        )}
      </div>
    </div>
  );
}

const styles = {
  whiteBox: { backgroundColor: '#fff', padding: '22px', borderRadius: '16px', border: '1px solid #e2e8f0', boxShadow: '0 2px 10px rgba(0,0,0,0.02)' },
  tabHeader: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderBottom: '2px solid #f1f5f9', paddingBottom: '14px', marginBottom: '16px' },
  filterBar: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: '10px', backgroundColor: '#f8fafc', padding: '10px 14px', borderRadius: '10px', border: '1px solid #e2e8f0', marginBottom: '18px' },
